mapper.select:
select t.day,
    ifnull((select count(*) from his_admission a where date(a.in_date) = t.day),'0') admitCnt,
    ifnull((select count(*) from his_admission a where date(a.out_date) = t.day),'0') dischargeCnt
from (
    select date_sub(curdate(), interval n day) day from (
        select 0 n union select 1 union select 2 union select 3 union select 4 union select 5 union select 6
        union select 7 union select 8 union select 9 union select 10 union select 11 union select 12 union select 13
    ) days
) t
order by t.day
